import{_ as r,l as i,o as e,c as l,v as t,p as s,x as n,d,i as E,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"做市商义务与撤退","description":"","frontmatter":{"title":"做市商义务与撤退","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-obligations-withdrawal.md","filePath":"quant/mm-obligations-withdrawal.md","lastUpdated":1789023840000}'),p={name:"quant/mm-obligations-withdrawal.md"};function c(h,a,A,B,u,_){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="做市商义务与撤退" tabindex="-1">做市商义务与撤退 <a class="header-anchor" href="#做市商义务与撤退" aria-label="Permalink to &quot;做市商义务与撤退&quot;">​</a></h1><div class="epigraph"><p>平静期自愿在场的做市商，在方差或库存越限时会关掉算法。义务条款试图把 Grossman–Miller 的 $M$ 在压力期钉住，但钉得太死会让人事先不愿进入，钉得太松则闪崩路径仍在。</p><footer>—— 据 Grossman and Miller, Liquidity and Market Structure, Journal of Finance, 1988；经验上做市商资本与撤退见 Anand and Venkataraman, Market conditions, fragility, and the economics of market making, Journal of Financial Economics, 2016</footer></div><p><a href="/quant/spoofing-layering">幌骚</a>是伪造供给。缺口是真实供给的<strong>选择性在场</strong>：高频做市没有传统专家那种硬义务时，Ho–Stoll 的限额变成撤退开关。Anand 与 Venkataraman（2016）讨论做市脆弱性；交易所指定做市商（DMM）、NASDAQ 做市商、期权指定商仍带有报价义务。本课写义务与撤退的权衡，接闪电崩盘的供给弹性，不写某司法辖区的条文清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自愿做市的进入条件是：平静期价差收入覆盖资本与被捡。压力期被捡与库存方差跳升，自愿最优是 \\(\\tau\\to 0\\) 直至离场。社会最优可能希望他们留下，因为即时性的外部性（别人的止损、价格作为公共信号）未被价差完全内部化。义务把留下写成约束：最大价差、最小深度、最短在场时间。问题是校准：义务过严，进入的 \\(M\\) 下降或要求更高的平时价差补贴；义务过松，约束在闪崩时恰好不绑定。</p><p>指定做市商常用特权（费用、信息、拍卖参与）交换义务。这是把 Ho–Stoll 的垄断租金部分退回，换压力期在场——Seppi 意义上专家与限价簿并存的制度版本。</p><h3 id="撤退是风控-不是一定是恶意" tabindex="-1">撤退是风控，不是一定是恶意 <a class="header-anchor" href="#撤退是风控-不是一定是恶意" aria-label="Permalink to &quot;撤退是风控，不是一定是恶意&quot;">​</a></h3><p>库存模型里硬约束使报价不连续：达到限额即单边或双边撤空。看起来像「扔下市场」，对个体是有限资本的最优。政策若惩罚撤退本身，等于要求无限资本，进入会少。更好的设计是熔断给补给时间、或中央对手方降低尾部，而不是假装 \\(M\\) 可以无限。</p><p><span class="marginnote">欧盟与美国对做市义务的写法不同，期权、期货、股票又不同。本课只保留「特权换在场」的机制，不比较法条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经验：识别指定做市商账户，比较义务股票与对照股票在压力窗的价差、深度、撤退概率。Anand–Venkataraman 强调资本与市场条件。事件：波动率跳升、相关市场中断、个股跳水。结果模式：自愿 HFT 深度比义务做市商更快消失；义务做市商在上限内加宽，但仍可能达到义务允许的最宽价差。</p><p>理论：Grossman–Miller 的进入均衡加一个「压力期必须在场」的约束，进入成本上升，平静期 \\(M\\) 可能下降。净福利取决于压力期外部性有多大——闪崩式分配损失 vs 平时更宽的价差。</p>',12)),(e(),s(m,null,{default:n(()=>[E(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Calm%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%E8%87%AA%E6%84%BF%E5%9C%A8%E5%9C%BA%22%5D%20--%3E%20Stress%5B%22%E6%96%B9%E5%B7%AE%20%2F%20%E5%BA%93%E5%AD%98%E8%B6%8A%E9%99%90%22%5D%0A%20%20Stress%20--%3E%20Exit%5B%22%E7%AE%97%E6%B3%95%E5%85%B3%E9%97%AD%22%5D%0A%20%20Obl%5B%22%E6%8A%A5%E4%BB%B7%E4%B9%89%E5%8A%A1%20%2B%20%E7%89%B9%E6%9D%83%22%5D%20--%3E%20Stay%5B%22%E5%8E%8B%E5%8A%9B%E6%9C%9F%E4%BB%8D%E6%8A%A5%E4%BD%86%E6%9B%B4%E5%AE%BD%22%5D%0A%20%20Exit%20--%3E%20Gap%5B%22%E7%A9%BA%E7%B0%BF%E8%B7%AF%E5%BE%84%22%5D%0A%20%20Stay%20--%3E%20Cost%5B%22%E8%BF%9B%E5%85%A5%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>义务把暂时折让的上界切开：价格不能完全沿空簿走，除非义务也被击穿或触发停牌。这与涨跌停、LULD 是同类的硬边界，只是实施者是做市商而不是引擎。代价是做市商在义务区间内承担更大库存，要求事先补偿，价差的处理与库存成分上升。信息成分不会因为义务消失：被捡仍在，义务商可能用更短寿命在允许范围内闪烁。</p><p>跨市场：一处有义务、相关处没有，压力会转到无义务场所先崩，再通过套利拖垮有义务的场所。义务必须认清领先市场在哪。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>义务不能创造资本。2010 年类事件里，若亏损超过资本，义务只是加快谁先破产。中央清算、保证金、熔断是配套。把「恢复专家垄断」当成解决 HFT 撤退的方案，会忽略电子簿在平静期的价差收益。混合设计（义务 + 自愿 HFT）是现实，纯模型两端都不存在。</p><p><span class="marginnote">考核做市商用「平时报价时长」会选出平静期挂机、压力期掉线的人。考核应加权尾部在场，尽管更难测量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自愿高频做市在压力期理性撤退；义务用特权换有界在场，但提高进入成本。</li><li>撤退是有限资本的库存约束，闪崩路径是加总结果。</li><li>跨市场义务不对称会把压力转移到领先的无义务场所。</li><li>出处：Grossman and Miller, <em>Journal of Finance</em>, 1988；Anand and Venkataraman, <em>Journal of Financial Economics</em>, 2016。</li></ul>',8))])}const b=r(p,[["render",c]]);export{D as __pageData,b as default};
